"""Built-in traceability profiles.

Spec: docs/specs/02-backstitch-core.md [SC-3]
"""

from __future__ import annotations

from typing import Any

from backstitch.config import ProfileConfig
from backstitch.diagnostics import load_default_config_raw


def _tuple(value: Any) -> tuple[str, ...]:
    if not isinstance(value, list) or not all(isinstance(item, str) for item in value):
        raise ValueError("packaged profile defaults must be arrays of strings")
    return tuple(value)


def _load_backstitch_style_v1() -> ProfileConfig:
    profile = load_default_config_raw()["profile"]
    return ProfileConfig(
        name=profile["name"],
        spec_roots=_tuple(profile["spec_roots"]),
        plan_roots=_tuple(profile["plan_roots"]),
        code_roots=_tuple(profile["code_roots"]),
        test_roots=_tuple(profile["test_roots"]),
        planned_spec_globs=_tuple(profile["planned_spec_globs"]),
        exploratory_spec_globs=_tuple(profile["exploratory_spec_globs"]),
        meta_spec_globs=_tuple(profile.get("meta_spec_globs", [])),
    )


BACKSTITCH_STYLE_V1 = _load_backstitch_style_v1()

_PROFILES: dict[str, ProfileConfig] = {
    BACKSTITCH_STYLE_V1.name: BACKSTITCH_STYLE_V1,
}


def get_profile(name: str) -> ProfileConfig:
    """Return a built-in profile by name.

    Raises ``ValueError`` for unknown names so the CLI can map the failure
    to exit code 2 [SC-5].
    """

    try:
        return _PROFILES[name]
    except KeyError:
        raise ValueError(f"unknown profile: {name!r}") from None

def _cmd_packets(args: argparse.Namespace) -> int:
    from backstitch.analysis_packets import generate_packets, render_packets_jsonl
    from backstitch.artifact_contracts import ValidatedSemanticPacket
    from backstitch.semantic_reports import atomic_replace_bytes, build_packet_report

    if args.report is not None:
        try:
            same_path = args.output.resolve(strict=False) == args.report.resolve(
                strict=False
            )
        except (OSError, RuntimeError) as exc:
            return _error(f"cannot resolve packet output/report paths: {exc}")
        if same_path:
            return _error("packet --output and --report paths must be distinct")

    settings = _resolve_settings(args)
    profile = _profile_from(args, settings)
    pipeline = build_check_report(args.repo_root, profile, settings)
    for warning in pipeline.warnings:
        print(f"warning: {warning}", file=sys.stderr)
    population = generate_packets(
        args.repo_root,
        profile,
        report=pipeline.report,
        kind="all",
    )
    packets = (
        population
        if args.kind == "all"
        else [packet for packet in population if packet["kind"] == args.kind]
    )
    rendered = render_packets_jsonl(packets).encode("utf-8")
    validated = tuple(
        ValidatedSemanticPacket.from_row(packet, cache_eligible=True)
        for packet in packets
    )
    packet_report = build_packet_report(
        packet_jsonl=rendered,
        packets=validated,
        kind=args.kind,
        eligible_counts={
            "section": sum(packet["kind"] == "section" for packet in population),
            "invariant": sum(packet["kind"] == "invariant" for packet in population),
        },
    )
    try:
        atomic_replace_bytes(args.output, rendered)
    except OSError as exc:
        return _error(f"cannot write --output {args.output}: {exc}")
    if args.report is not None:
        try:
            atomic_replace_bytes(args.report, packet_report.to_json_bytes())
        except OSError as exc:
            return _error(f"cannot write --report {args.report}: {exc}")
    print(f"wrote {len(packets)} packets to {args.output}", file=sys.stderr)
    # [SC-5]: packets still reports the deterministic scan outcome -- the
    # packets were written either way, but exit 1 says findings exist.
    return (
        1
        if any(
            issue.severity in set(settings.diagnostics.fail_on)
            for issue in pipeline.report.issues
        )
        else 0
    )

def doctor_exit_code(results: list[CheckResult]) -> int:
    """[SC-14]/[SC-5]: 0 iff no check failed; otherwise 2, never 1."""

    return 2 if any(result.status == "fail" for result in results) else 0

def _generate_section_packets(
    repo_root: Path,
    profile: ProfileConfig,
    report: Report,
) -> list[dict[str, Any]]:
    """Generate one section packet for each spec section with resolved edges."""

    sections_by_file: dict[str, list[SpecSection]] = {}
    for section in report.spec_sections:
        sections_by_file.setdefault(section.path, []).append(section)

    spec_lines: dict[str, list[str]] = {}
    for path in sections_by_file:
        spec_lines[path] = (
            (repo_root / path)
            .read_text(encoding="utf-8", errors="replace")
            .splitlines()
        )

    edges_by_key: dict[tuple[str, str], list] = {}
    for edge in report.edges:
        edges_by_key.setdefault((edge.spec_path, edge.section_id), []).append(edge)

    packets: list[dict[str, Any]] = []
    seen_keys: set[tuple[str, str]] = set()
    for section in report.spec_sections:
        key = (section.path, section.section_id)
        if key in seen_keys:
            continue
        seen_keys.add(key)
        edges = edges_by_key.get(key, [])
        if not edges:
            continue

        warnings: list[str] = []
        owner_keys: list[tuple[str, str | None]] = []
        tests: list[str] = []
        for edge in edges:
            if _is_test_path(repo_root, edge.code_path, profile.test_roots):
                if edge.code_path not in tests:
                    tests.append(edge.code_path)
                continue
            symbol = edge.code_symbol
            if edge.kind == "backlink" and symbol == "module":
                symbol = None
            owner_key = (edge.code_path, symbol)
            if owner_key not in owner_keys:
                owner_keys.append(owner_key)

        if len(owner_keys) > MAX_OWNERS_PER_PACKET:
            omitted = len(owner_keys) - MAX_OWNERS_PER_PACKET
            owner_keys = owner_keys[:MAX_OWNERS_PER_PACKET]
            warnings.append(f"{omitted} additional owners omitted")

        owners = []
        for path, symbol in owner_keys:
            snippet, start_line = _owner_snippet(repo_root, path, symbol, warnings)
            owners.append(
                {
                    "path": path,
                    "symbol": symbol,
                    "start_line": start_line,
                    "snippet": snippet,
                }
            )
        owners.sort(
            key=lambda item: (
                item["path"],
                item["symbol"] or "",
                item["start_line"],
            )
        )
        tests.sort()

        owner_paths = {path for path, _ in owner_keys}
        issues = [
            {field: dataclasses.asdict(issue)[field] for field in ISSUE_FIELDS}
            for issue in report.issues
            if issue.section_id == section.section_id
            and (
                issue.path == section.path
                or issue.path in owner_paths
                or issue.path in tests
            )
        ]

        packet: dict[str, Any] = {
            "schema_version": 2,
            "packet_id": f"{section.path}#{section.section_id}",
            "kind": "section",
            "spec_path": section.path,
            "section_id": section.section_id,
            "title": section.title,
            "section_text": _section_text(
                section,
                spec_lines[section.path],
                sections_by_file[section.path],
                warnings,
            ),
            # [SC-6]: the section's starting line anchors evidence
            # line-locality checks against the shown section text.
            "section_start_line": section.line,
            "owners": owners,
            "tests": tests,
            "issues": issues,
            # [SC-6] field name is contractual: consumers look for
            # `packet_warnings` for truncation/omission context.
            "packet_warnings": warnings,
        }
        packet["packet_hash"] = semantic_packet_hash(packet)
        packets.append(packet)
    return packets

def _packet_evidence_bounds(
    packet: dict[str, Any],
) -> dict[str, tuple[tuple[int, int], ...]]:
    """What the model was shown, as path -> allowed line ranges ([SC-7]).

    Owner snippets and the spec section text are line-bounded, so evidence
    must fall inside one of those ranges. Linked tests are named by PATH
    only -- the model never saw their content, so a path with no ranges is
    known to the packet but cannot carry line evidence.
    """

    if packet.get("kind", "section") == "invariant":
        return _snippet_evidence_bounds(
            (*packet.get("targets", ()), *packet.get("binding_tests", ()))
        )

    bounds: dict[str, list[tuple[int, int]]] = {}
    spec_path = packet.get("spec_path")
    # Blank paths never name a packet member: an empty or whitespace-only
    # string must not become a citable evidence path (load-time validation
    # rejects these, but analyze_packets is also a library entry point).
    if isinstance(spec_path, str) and spec_path.strip():
        ranges = bounds.setdefault(spec_path, [])
        start = packet.get("section_start_line")
        text = packet.get("section_text")
        if isinstance(start, int) and isinstance(text, str) and text.splitlines():
            ranges.append((start, start + len(text.splitlines()) - 1))
    for test in packet.get("tests", ()):
        if isinstance(test, str) and test.strip():
            bounds.setdefault(test, [])
    for owner in packet.get("owners", ()):
        if (
            not isinstance(owner, dict)
            or not isinstance(owner.get("path"), str)
            or not owner["path"].strip()
        ):
            continue
        ranges = bounds.setdefault(owner["path"], [])
        start = owner.get("start_line")
        snippet = owner.get("snippet")
        # An EMPTY snippet (directory mappings) showed no line content:
        # like tests, the path is known but carries no valid line evidence.
        if isinstance(start, int) and isinstance(snippet, str) and snippet.splitlines():
            ranges.append((start, start + len(snippet.splitlines()) - 1))
    return {path: tuple(ranges) for path, ranges in bounds.items()}

def validate_analysis_row(
    row: Any,
    known_packet_ids: set[str] | Mapping[str, str] | None,
    *,
    allowed_evidence: Mapping[str, tuple[tuple[int, int], ...]] | None = None,
) -> AnalysisResult | str:
    """Validate one untrusted model-output row ([SC-7]).

    ``allowed_evidence``, when provided, keeps evidence packet-local: the
    model may only cite paths that were in the packet it was shown, and
    only lines inside one of that path's ``(start, end)`` inclusive
    ranges. An empty range tuple means the path was named in the packet
    WITHOUT line-bounded content (linked tests): it cannot carry line
    evidence at all -- any cited line there is fabricated.
    """

    if not isinstance(row, dict):
        return "row is not a JSON object"
    if "schema_version" in row:
        return _validate_v2_analysis_row(row, known_packet_ids)
    if "packet_hash" in row or "analysis_key" in row or "verification_state" in row:
        return "partial v2 result markers require `schema_version = 2`"
    packet_id = row.get("packet_id")
    if not isinstance(packet_id, str) or not packet_id.strip():
        return "missing or invalid `packet_id`"
    kind: str
    content_hash: str | None
    if "kind" not in row:
        if "content_hash" in row:
            return "legacy section result must omit `content_hash`"
        if packet_id.startswith("invariant::"):
            return "missing `kind` for invariant result identity"
        kind = "section"
        content_hash = None
    else:
        raw_kind = row.get("kind")
        if raw_kind not in CLASSIFICATIONS_BY_KIND:
            return "invalid `kind`; expected `section` or `invariant`"
        kind = raw_kind
        if kind == "section":
            if "content_hash" in row:
                return "section result must omit `content_hash`"
            if packet_id.startswith("invariant::"):
                return "section result cannot use an invariant packet identity"
            content_hash = None
        else:
            prefix = "invariant::"
            invariant_id = packet_id.removeprefix(prefix)
            if not packet_id.startswith(prefix) or not is_valid_section_id(
                invariant_id
            ):
                return "invariant result requires `invariant::<ID>` packet identity"
            raw_hash = row.get("content_hash")
            if not isinstance(raw_hash, str) or not _CONTENT_HASH_RE.fullmatch(
                raw_hash
            ):
                return (
                    "invalid `content_hash`; expected 64 lowercase hexadecimal"
                    " characters"
                )
            content_hash = raw_hash

    if known_packet_ids is not None:
        if packet_id not in known_packet_ids:
            return f"unknown packet ID `{packet_id}`"
        if isinstance(known_packet_ids, Mapping):
            expected_kind = known_packet_ids[packet_id]
            if kind != expected_kind:
                return (
                    f"result kind `{kind}` does not match packet kind `{expected_kind}`"
                )
    classification = row.get("classification")
    allowed_classifications = CLASSIFICATIONS_BY_KIND[kind]
    if classification not in allowed_classifications:
        return (
            f"unsupported classification {classification!r} for {kind} result;"
            f" expected one of {', '.join(allowed_classifications)}"
        )
    summary = row.get("summary")
    if not isinstance(summary, str) or not summary.strip():
        # Blank means absent, same as locators and rationales.
        return "missing or invalid `summary`"
    confidence = row.get("confidence")
    if confidence is not None and (
        isinstance(confidence, bool)
        or not isinstance(confidence, int | float)
        or not 0.0 <= confidence <= 1.0
    ):
        # The prompt contract asks for a confidence between 0 and 1;
        # anything else is a malformed row, not a very confident one.
        return "invalid `confidence`; expected a number between 0 and 1"
    rationale = row.get("rationale")
    if rationale is None:
        rationale = ""
    if not isinstance(rationale, str):
        return "invalid `rationale`; expected a string"
    if confidence is None and not rationale.strip():
        # The [SC-7] record contract requires a confidence OR rationale
        # field; a row carrying neither is malformed, not low-effort.
        return "missing `confidence` or `rationale`; rows must carry at least one"
    evidence_raw = row.get("evidence")
    evidence: list[tuple[str, int]] = []
    if not isinstance(evidence_raw, list):
        # `evidence` is a required key (an empty list is a valid value:
        # it states explicitly that no evidence is cited).
        return "missing or invalid `evidence`; expected a list"
    for item in evidence_raw:
        if (
            not isinstance(item, dict)
            or not isinstance(item.get("path"), str)
            or not item["path"].strip()
            or isinstance(item.get("line"), bool)
            or not isinstance(item.get("line"), int)
            or item["line"] < 1
        ):
            return "invalid `evidence` item; expected {non-empty path, line >= 1}"
        if allowed_evidence is not None:
            # [SC-7]: model output is untrusted; evidence must stay inside
            # the packet boundary -- both the path and the line.
            ranges = allowed_evidence.get(item["path"])

def _cmd_eval(args: argparse.Namespace) -> int:
    # Like analyze, eval is an explicitly model-touching command. Keep all
    # provider imports inside this handler so deterministic commands retain
    # the structural no-llm guarantee ([SC-8]).
    try:
        if args.corpus.resolve() == args.output.resolve():
            raise ConfigLoadError("eval --corpus and --output paths must be distinct")
    except OSError as exc:
        raise ConfigLoadError(f"eval path resolution failed: {exc}") from exc

    from dataclasses import replace

    from backstitch.analysis_llm import default_provider_adapter, resolve_model_name
    from backstitch.semantic_analysis import resolve_semantic_settings
    from backstitch.semantic_cache import ProviderAdapter
    from backstitch.semantic_eval import (
        SemanticEvalError,
        SemanticEvalRequest,
        run_semantic_eval,
    )
    from backstitch.semantic_policy import materialize_semantic_policy

    anchor = args.corpus.resolve().parent
    if args.no_config and args.config is not None:
        raise ConfigLoadError("--config and --no-config are mutually exclusive")
    if args.no_config:
        settings = load_settings(anchor, use_repo_config=False)
    else:
        settings = load_settings(anchor, explicit=args.config)
    model_name = resolve_model_name(None, configured=settings.analyze.model or None)
    configured_model = settings.analyze.model.strip()
    if (
        settings.analyze.cache_mode in {"read-write", "require"}
        and configured_model
        and model_name != configured_model
    ):
        raise ConfigLoadError(
            "cached model override disagrees with configured model/revision pair; "
            "use a config that declares both values"
        )
    analyze_settings = replace(settings.analyze, model=model_name or "")
    resolved = resolve_semantic_settings(analyze_settings)
    profile = _configured_profile(settings)
    _validate_test_root_containment(anchor, profile)
    policy = materialize_semantic_policy(
        settings.diagnostics,
        settings.policy_rule_origins,
        settings.config_layers,
    )

    def build_adapter() -> ProviderAdapter:
        return default_provider_adapter(
            model_name,
            provider_identity=resolved.provider_identity,
            request_identity=resolved.request_identity,
        )

    try:
        run = run_semantic_eval(
            SemanticEvalRequest(
                manifest_path=args.corpus,
                output_path=args.output,
                profile=profile,
                exclude_globs=settings.exclude,
                settings=resolved,
                eval_settings=settings.analyze.eval,
                policy=policy,
                adapter_factory=(
                    build_adapter if resolved.cache_mode == "read-write" else None
                ),
            )
        )
    except SemanticEvalError as exc:
        raise SemanticEvalError(f"{args.corpus}: {exc}") from exc
    for line in run.stderr_lines:
        print(line, file=sys.stderr)
    return run.exit_code

def _cmd_doctor(args: argparse.Namespace) -> int:
    # Lazy import in the handler only: doctor is an llm-touching command
    # like analyze; check/packets stay structurally incapable of importing
    # llm ([SC-8]), and doctor.py itself defers llm to check functions.
    from backstitch.doctor import (
        doctor_exit_code,
        render_json,
        render_text,
        run_doctor,
    )

    # [CFG-3]: doctor anchors config discovery at the current working
    # directory (it has no packets file or --repo-root to anchor on).
    if args.no_config and args.config is not None:
        raise ConfigLoadError("--config and --no-config are mutually exclusive")
    if args.no_config:
        settings = load_settings(Path.cwd(), use_repo_config=False)
    else:
        settings = load_settings(Path.cwd(), explicit=args.config)
    results = run_doctor(
        args.model, configured=settings.analyze.model, probe=args.probe
    )
    rendered = render_json(results) if args.format == "json" else render_text(results)
    sys.stdout.write(rendered)
    return doctor_exit_code(results)

"""Diagnostic registry, aliases, and ordered reporting policy.

Spec: docs/specs/02-backstitch-core.md [SC-6], [SC-11], [SC-15]
Spec: docs/specs/03-backstitch-configuration.md [CFG-5], [CFG-6], [CFG-8]
Spec: docs/specs/04-backstitch-traceability-exclusions.md [EXC-4], [EXC-8]
Spec: docs/specs/05-backstitch-invariants.md [INV-4], [INV-8]
"""

from __future__ import annotations

import dataclasses
import functools
import importlib.resources
import tomllib
from dataclasses import dataclass
from typing import Any, Literal

Severity = Literal["error", "warning", "info"]
DiagnosticLevel = Literal["error", "warning", "info", "off"]
DiagnosticStatus = Literal["implemented", "reserved", "deprecated", "redirected"]

SEVERITIES: frozenset[str] = frozenset({"error", "warning", "info"})
DIAGNOSTIC_LEVELS: frozenset[str] = frozenset({"error", "warning", "info", "off"})
DIAGNOSTIC_STATUSES: frozenset[str] = frozenset(
    {"implemented", "reserved", "deprecated", "redirected"}
)
DEFAULTS_RESOURCE = "defaults.toml"
OFF_AUDIT_REASON = "diagnostic level off"
SEMANTIC_DIAGNOSTIC_PREFIX = "SEMANTIC_"


class DiagnosticConfigError(ValueError):
    """The packaged diagnostic registry or configured policy is invalid."""


@dataclass(frozen=True, slots=True)
class DiagnosticDefinition:
    code: str
    short_code: str
    status: DiagnosticStatus
    summary: str
    contexts: tuple[str, ...] = ()
    replacement: str | None = None


@dataclass(frozen=True, slots=True)
class DiagnosticRegistry:
    definitions: dict[str, DiagnosticDefinition]
    short_to_code: dict[str, str]

    def require(self, code: str) -> DiagnosticDefinition:
        try:
            return self.definitions[code]
        except KeyError:
            raise DiagnosticConfigError(f"unknown diagnostic code: {code}") from None

    def canonical_code(self, code_or_short: str) -> str:
        if code_or_short in self.definitions:
            code = code_or_short
        elif code_or_short in self.short_to_code:
            code = self.short_to_code[code_or_short]
        else:
            raise DiagnosticConfigError(f"unknown diagnostic code: {code_or_short}")

        chain: list[str] = []
        seen: set[str] = set()
        while True:
            if code in seen:
                cycle = " -> ".join((*chain, code))
                raise DiagnosticConfigError(
                    f"diagnostic replacement cycle detected: {cycle}"
                )
            seen.add(code)
            chain.append(code)

            definition = self.require(code)
            if definition.status == "implemented":
                return code
            if definition.status not in {"deprecated", "redirected"}:
                raise DiagnosticConfigError(
                    f"diagnostic {code_or_short} resolves to {code} with status"
                    f" {definition.status}; expected implemented"
                )
            if definition.replacement is None:
                raise DiagnosticConfigError(
                    f"diagnostic {code} has status {definition.status} but no replacement"
                )
            if definition.replacement not in self.definitions:
                raise DiagnosticConfigError(
                    f"diagnostic {code} replacement is not a known diagnostic:"
                    f" {definition.replacement}"
                )
            code = definition.replacement

    def implemented_codes(self) -> frozenset[str]:
        return frozenset(
            code
            for code, definition in self.definitions.items()
            if definition.status == "implemented"
        )


@dataclass(frozen=True, slots=True)
class DiagnosticLevelRule:
    selectors: tuple[str, ...]
    level: DiagnosticLevel


@dataclass(frozen=True, slots=True)
class DiagnosticsSettings:
    default_level: DiagnosticLevel = "warning"
    levels: tuple[DiagnosticLevelRule, ...] = ()
    fail_on: tuple[Severity, ...] = ("error",)
    suppressible_levels: tuple[Severity, ...] = ("warning", "info")


@functools.cache
def load_default_config_raw() -> dict[str, Any]:
    """Return Backstitch's packaged default TOML body."""

