"""Sibling repository discovery for target corpus checks.

Spec: docs/specs/02-backstitch-core.md [SC-12]
Spec: docs/specs/03-backstitch-configuration.md [CFG-5], [CFG-6]

Discovery precedence: environment override, then configured
``[target_roots]`` path, then the sibling of the MAIN repository checkout.
The worktree case is the one that breaks in practice ([SC-12]): naive
``<checkout-parent>/<name>`` resolves to ``.worktrees/<name>`` from a linked
worktree, so worktree paths are normalized to the main repository root
before sibling lookup.
"""

from __future__ import annotations

import os
import subprocess
from pathlib import Path

from backstitch.settings import BackstitchSettings

_ENV_OVERRIDES = {
    "weft": "BACKSTITCH_WEFT_ROOT",
}


def git_worktree_root(start: Path | None = None) -> Path:
    """Return the root of the current git worktree."""

    start_path = (start or Path.cwd()).resolve()
    try:
        toplevel = subprocess.check_output(
            ["git", "rev-parse", "--show-toplevel"],
            cwd=start_path,
            text=True,
            stderr=subprocess.DEVNULL,
        ).strip()
    except (subprocess.CalledProcessError, FileNotFoundError):
        return start_path
    return Path(toplevel).resolve()


def git_main_repo_root(start: Path | None = None) -> Path:
    """Normalize a worktree checkout path to the main repository root."""

    root = git_worktree_root(start)
    parts = root.parts
    if ".worktrees" in parts:
        index = parts.index(".worktrees")
        return Path(*parts[:index])
    return root


def discover_sibling_repo(
    name: str,
    *,
    anchor: Path | None = None,
    configured_path: str | None = None,
) -> Path | None:
    """Locate a sibling repository directory next to the main repo."""

    env_key = _ENV_OVERRIDES.get(name.lower())
    if env_key:
        override = os.environ.get(env_key)
        if override:
            path = Path(override).expanduser().resolve()
            if path.is_dir():
                return path

    if configured_path:
        path = Path(configured_path).expanduser().resolve()
        if path.is_dir():
            return path

    main_repo = git_main_repo_root(anchor)
    candidate = main_repo.parent / name
    if candidate.is_dir():
        return candidate.resolve()
    return None


def discover_weft(
    *,
    anchor: Path | None = None,
    settings: BackstitchSettings | None = None,
) -> Path | None:
    configured = settings.target_roots.weft if settings is not None else None
    return discover_sibling_repo("weft", anchor=anchor, configured_path=configured)

def _check_endpoint(model: Any | None, probe: bool) -> CheckResult:
    if not probe:
        return CheckResult(
            "endpoint", "skip", "not evaluated: run with --probe to test"
        )
    if model is None:
        return CheckResult("endpoint", "skip", "not evaluated: model unresolved")
    api_base = getattr(model, "api_base", None)
    if not api_base:
        return CheckResult(
            "endpoint",
            "skip",
            "not evaluated: resolved model has no api_base endpoint",
        )

    import http.client
    import time
    import urllib.error

    # The probed url is stripped of userinfo/query so no credential in
    # api_base ever reaches the wire ([SC-14] unauthenticated GET); the same
    # credential-free string is what every detail shows. A malformed api_base
    # (bad scheme/host or a non-integer port) is an endpoint failure, never an
    # uncaught traceback that would drop the ordered check report.
    url = _safe_models_url(api_base)
    if url is None:
        return CheckResult(
            "endpoint",
            "fail",
            "resolved model api_base is not a valid http(s) URL",
            "fix the model registration's api_base to scheme://host[:port]/path",
        )
    # [SC-14]: any status other than 200/401/403 is a failure — a silently
    # followed 3xx would both hide the status and probe a different URL, so
    # redirects are surfaced as their raw status instead of followed.
    opener = urllib.request.build_opener(_NoRedirect)
    try:
        request = urllib.request.Request(url, headers={"Accept": "application/json"})
        with opener.open(request, timeout=PROBE_TIMEOUT_SECONDS) as response:
            body, overrun = _read_bounded(
                response, PROBE_MAX_BODY_BYTES, PROBE_TIMEOUT_SECONDS, time
            )
    except urllib.error.HTTPError as exc:
        if exc.code in (401, 403):
            return CheckResult(
                "endpoint",
                "pass",
                f"{url} reachable; model list is authentication-gated "
                f"(HTTP {exc.code}), membership not verified",
            )
        return CheckResult(
            "endpoint",
            "fail",
            f"{url} answered HTTP {exc.code}",
            "confirm the endpoint serves a standard model-list route at /models",
        )
    except (
        urllib.error.URLError,
        TimeoutError,
        OSError,
        ValueError,
        http.client.HTTPException,
    ) as exc:
        return CheckResult(
            "endpoint",
            "fail",
            f"{url} is unreachable: {_one_line(str(exc))}",
            "start the local model server (or fix the model registration's "
            "api_base; see the README local-lane section), then re-run "
            "with --probe",
        )
    if overrun:
        return CheckResult(
            "endpoint",
            "fail",
            f"{url} did not deliver a bounded model list (over "
            f"{PROBE_MAX_BODY_BYTES} bytes or past the "
            f"{PROBE_TIMEOUT_SECONDS} s budget)",
            "confirm the endpoint serves a standard model-list route at /models",
        )

    try:
        payload = json.loads(body)
    except ValueError:
        payload = None
    if not isinstance(payload, dict) or not isinstance(payload.get("data"), list):
        return CheckResult(
            "endpoint",
            "fail",
            f"{url} answered 200 but not with a standard model-list payload",
            "confirm the endpoint serves a standard model-list route at /models",
        )

    served = getattr(model, "model_name", None) or getattr(model, "model_id", "")
    ids = [
        str(item.get("id"))
        for item in payload["data"]
        if isinstance(item, dict) and item.get("id") is not None
    ]
    if served in ids:
        return CheckResult("endpoint", "pass", f"{url} reachable; {served!r} is served")
    return CheckResult(
        "endpoint",
        "fail",
        f"{url} reachable but {served!r} is not in the served model list: {ids}",
        "pull or load the model on the server, or point model_name at one "
        "of the served ids",
    )

